def _add_global_secondary_index(ret, name, index_name, changes_old, changes_new, comments,
                                gsi_config, region, key, keyid, profile):
    """Updates ret iff there was a failure or in test mode."""
    if not ret['success']:
        return ret
    if not __opts__['test']:
        if not gsi_config:
            gsi_config = __salt__['boto_dynamodb.get_table'](
                name, region=region, key=key, keyid=keyid, profile=profile)
        if gsi_config:
            if index_name in gsi_config['global_secondary_indexes']:
                gsi_config['global_secondary_indexes'][index_name]['provisioned_throughput'] = changes_new
            else:
                gsi_config['global_secondary_indexes'][index_name] = {
                    'provisioned_throughput': changes_new,
                    'index_name': index_name
                }
            ret['changes'][name] = {
                'old': changes_old,
                'new': changes_new,
            }
            ret['comment'] = comments
            if __opts__['test']:
                ret['result'] = None
                return ret
            __salt__['boto_dynamodb.update_table'](
                name, gsi_config, region=region, key=key, keyid=keyid, profile=profile)
            if __salt__['boto_dynamodb.get_table'](
                    name, region=region, key=key, keyid=keyid, profile=profile)['global_secondary_indexes'][index_name]['provisioned_throughput'] == changes_new:
                ret['result'] = True
                ret['comment'] = comments
                return ret
            else:
                ret['result'] = False
                ret['comment'] = 'Failed to update global secondary index'
                return ret
    return ret

